function _move(x, y) {
  _params.x = Math.max(0, Math.min(1, x));
  _params.y = Math.max(0, Math.min(1, y));

  _trail.push({ x: _params.x, y: _params.y, t: Date.now() });
  if (_trail.length > TRAIL_MAX) _trail.shift();

  /* Broadcast modulation */
  gBus.publish('mod:xy', {
    instanceId,
    x:     _params.x,
    y:     _params.y,
    xDest: _params.xDest,
    yDest: _params.yDest,
  });

  sBus.publish('org:xy_update', {
    x:     _params.x,
    y:     _params.y,
    trail: _trail.slice(),
  });
}
